-- +goose Up
-- Запись релиза в журнал (notified_at NULL — бот уведомит админа на старте).
-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.85.0',
  '2026-09-03',
  'Сейф: временные ссылки, действия над файлом и просмотр docx/zip',
  E'Сейф стал удобнее. У каждой карточки появилась кнопка «⋯»: переименовать файл, добавить к нему заметку, сделать копию в другой папке, поставить срок жизни, посмотреть журнал и удалить. Имя и заметка шифруются вместе — сервер их по-прежнему не видит.\n\nВыбор файлов теперь видно: кнопка «☑️» включает режим выбора, на карточках появляются кружки, работает долгое нажатие и «Все». Дальше выбранное можно перенести, удалить или выгрузить архивом. Появился поиск по именам и заметкам внутри открытой папки.\n\nВременная ссылка на один файл: «⋯ → Ссылка», срок от 15 минут до недели и, если нужно, лимит открытий. Открывший ссылку всё равно вводит пароль — задайте для ссылки отдельный и передайте его другим каналом. Ссылка показывается один раз, её можно отозвать, а в журнале видно, когда её открывали.\n\nПросмотр научился листать: стрелки, свайп и кнопки переключают файлы папки, картинку можно приблизить. Открываются docx (текст, заголовки, списки) и zip (список содержимого).\n\nПапке можно включить «не показывать подпапки, пока не введён пароль» (это косметика: имена папок сервер знает) и срок жизни для загружаемых в неё файлов. Прерванная загрузка продолжается с места обрыва, а не с начала.',
  E'Миграция 0119: vault_links (только SHA-256 токена, отдельные salt/iter и конверты), vault_access_log, vault_folders.hide_children/auto_delete_days, vault_files.expires_at. Заметка к файлу отдельной колонки не получила — она внутри meta_env, иначе сервер читал бы её открытым текстом.\n\nВременные ссылки (вариант А из PLAN-vault.md): при создании браузер разворачивает ключ содержимого ключом папки и заворачивает заново под пароль ссылки — ключ папки наружу не уходит, утёкшая ссылка компрометирует один файл и только вместе с паролем. Имя и тип шифруются тем же ключом: meta_env папки получателю расшифровать нечем. Токен 32 байта base64url, в базе только хеш. Открытие засчитывается на выдаче блоба, а не на загрузке страницы. Просроченная, исчерпанная, отозванная и несуществующая ссылки дают одинаковый 404.\n\nПубличная страница /l/{token} — вне авторизации, как /read/{token}. Заодно починены обе: RouteMeta.public отключает TokenGate, меню и шапку, а main.ts не дёргает закрытые ручки — раньше страница чтения статьи в чистом браузере упиралась бы в экран ввода токена.\n\nКопия файла — переворот ключа плюс копия байтов на диске (перезаливки и перешифровки нет), квота проверяется у владельца целевой папки. Возобновление загрузки: GET /vault/uploads/{uid} отдаёт принятые байты, чанк пишется целиком или никак (тело читается в память до записи), поэтому счётчик всегда на границе чанка. Уборщик раз в час сносит просроченные файлы, старые ссылки и записи журнала старше 90 дней.\n\ndocx разбирается через fflate + DOMParser (абзацы, заголовки, жирный/курсив, списки) — mammoth на мегабайт не тянули; разметка собирается из экранированного текста. zip — список содержимого, выгрузка папки — zipSync без сжатия (содержимое уже несжимаемо).\n\nПроверено сквозняком в браузере: загрузка перетаскиванием, поиск по именам и заметкам, режим выбора с кружками и «Все», массовое удаление с возвратом квоты, листание и зум в просмотрщике, docx с экранированным <тегом>, список zip, создание/отзыв ссылки из интерфейса, открытие ссылки без авторизации (неверный пароль не тратит открытие, лимит открытий срабатывает, битый токен — 404), копия файла читается ключом другой папки, наследование срока от папки, скрытие подпапок до пароля, замок чистит blob-URL, возобновление 3-чанковой загрузки с середины — файл на 5 МБ расшифровался побайтно.'
);
-- +goose StatementEnd

